import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Directional key light: 35deg elevation for anisotropic sweep
  const elevRad = Math.PI / 5.14; // ~35 degrees
  const light = new THREE.DirectionalLight(0xffffff, 1.0);
  light.position.set(
    2 * Math.cos(elevRad),
    2 * Math.sin(elevRad),
    0
  );
  light.target.position.set(0, 0, 0);
  group.add(light);
  group.add(light.target);

  // Brushed-metal PBR material with vertical albedo ramp
  const tileMaterial = new THREE.MeshStandardNodeMaterial({
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    color: 0x1a1a22,
  });

  // Grid layout: 3 cols × 2 rows, each 1.0w × 0.62h, gap 0.25
  const tileData = [
    // Row 0 (top): left-to-right
    { x: -1.25, y: 0.435, text: 'HODINKEE' },
    { x: 0, y: 0.435, text: 'MONOCLE' },
    { x: 1.25, y: 0.435, text: 'WALLPAPER' },
    // Row 1 (bottom): left-to-right
    { x: -1.25, y: -0.435, text: 'ESQUIRE' },
    { x: 0, y: -0.435, text: 'WIRED' },
    { x: 1.25, y: -0.435, text: 'FINANCIAL TIMES' },
  ];

  const tiles = [];
  tileData.forEach((item) => {
    const tile = new THREE.Group();
    tile.position.set(item.x, item.y, 0);

    // Tile plane mesh
    const tileGeom = new THREE.PlaneGeometry(1.0, 0.62);
    const tileMesh = new THREE.Mesh(tileGeom, tileMaterial);
    tile.add(tileMesh);

    // Brand wordmark text mesh
    const textMesh = createBrandMark(item.text, ctx);
    tile.add(textMesh);

    group.add(tile);
    tiles.push(tile);
  });

  // Kicker text: "AS FEATURED IN" positioned above grid
  const kickerMesh = createKicker(ctx);
  kickerMesh.position.y = 1.045;
  group.add(kickerMesh);

  // Hover state management
  const hoverTimelines = new Map();

  group.userData.handlers = {
    onPointerEnter: (tileIndex) => {
      const tile = tiles[tileIndex];
      if (hoverTimelines.has(tileIndex)) {
        hoverTimelines.get(tileIndex).kill();
      }
      const tl = gsap.timeline();
      // Lift tile and fade text to full opacity
      tl.to(tile.position, { z: 0.05, duration: 0.16, ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)' }, 0);
      if (tile.children[1]) {
        tl.to(tile.children[1].material, { opacity: 1.0, duration: 0.16, ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)' }, 0);
      }
      hoverTimelines.set(tileIndex, tl);
    },
    onPointerLeave: (tileIndex) => {
      const tile = tiles[tileIndex];
      if (hoverTimelines.has(tileIndex)) {
        hoverTimelines.get(tileIndex).kill();
      }
      const tl = gsap.timeline();
      // Return to baseline
      tl.to(tile.position, { z: 0, duration: 0.16, ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)' }, 0);
      if (tile.children[1]) {
        tl.to(tile.children[1].material, { opacity: 0.78, duration: 0.16, ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)' }, 0);
      }
      hoverTimelines.set(tileIndex, tl);
    },
  };

  // Mount animation: stagger-cards (fade-up, 80ms stagger)
  // Order: top row left-to-right first (tiles 0,1,2,3,4,5)
  gsap.fromTo(tiles,
    {
      opacity: 0,
      y: (i) => tiles[i].position.y + 0.2,
    },
    {
      opacity: 1,
      y: (i) => tiles[i].position.y,
      duration: 0.5,
      stagger: 0.08,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
    }
  );

  // Cleanup: kill all tweens and dispose resources
  group.userData.cleanup = () => {
    hoverTimelines.forEach(tl => {
      if (tl) tl.kill();
    });
    gsap.killTweensOf(tiles);
    tileMaterial.dispose();
  };

  return group;
}

/**
 * Create brand wordmark text mesh using MSDF font atlas.
 * Text is monochrome #e8ecf2 at 78% opacity, positioned flat above each tile.
 */
function createBrandMark(text, ctx) {
  const mesh = ctx.fontAtlas.createMesh(text, {
    family: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 700,
    letterSpacing: 0.08,
    lineHeight: 1,
    color: 0xe8ecf2,
    opacity: 0.78,
    align: 'center',
  });

  // Position text flat above the tile surface
  mesh.position.z = 0.02;

  return mesh;
}

/**
 * Create kicker ("AS FEATURED IN") text mesh.
 * Positioned 0.3 units above the grid center.
 */
function createKicker(ctx) {
  const mesh = ctx.fontAtlas.createMesh('AS FEATURED IN', {
    family: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 700,
    letterSpacing: 0.12,
    lineHeight: 1.2,
    color: 0xe8ecf2,
    opacity: 1.0,
    align: 'center',
  });

  mesh.position.z = 0.0;

  return mesh;
}
